# aeneid-087 (XI.532-647): t is cut from the edition by A.cut; l, i, n drafted from the Latin.
import sys, os
HERE = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, HERE); sys.path.insert(0, os.path.join(HERE, '..', '..'))
import aeneid_lib as A

TITLE = 'Camillae infantia. Pugna equestris'
PART = "Camilla's Childhood and the Cavalry Battle (XI.532–647)"
TITLE_EN = "Camilla's Childhood and the Cavalry Battle — Aeneid XI.532–647"
ABOUT = ("While Turnus lies in wait in the hills, the poem turns to heaven. "
"Diana, daughter of Latona, speaks sadly to Opis, one of her nymphs: Camilla is riding to a war that will kill her, and the goddess's love for her is old. "
"She tells the story. Metabus, king of the Volscian town of Privernum, was driven out for his harsh rule and fled with his baby daughter, whom he named Camilla after her mother Casmilla. "
"Cornered by pursuers at the flooded river Amasenus, he bound the child to his spear, vowed her to Diana as her servant, and hurled her across; then he swam over and took her up. "
"No city would shelter him, and he raised her in the wild mountains on mares' milk, armed her as soon as she could walk, and dressed her in a tiger's skin; she hunted cranes and swans with sling and javelin, and turned away every offer of marriage to serve Diana. "
"The goddess wishes she had kept out of this war, and since her fate is fixed she sends Opis down with an arrow of vengeance for whoever wounds her, promising to carry the body home in a cloud. "
"Then the cavalry battle begins: the Trojans and Etruscans advance on the city, Messapus, Coras and Camilla's squadron ride out against them, and the spears fly like snow. "
"Aconteus is killed in the first shock, the Latins break for the walls, rally, and are driven back again, the two sides surging to and fro like the tide on a beach; at the third clash the lines lock together, Orsilochus brings down Remulus by wounding his horse, and Catillus kills Iollas and the giant Herminius.")

U = [
(535, 'dabat:',
 """Swift, meanwhile, in the seats above, Opis,\none of the maidens her companions and her sacred band,\nwas addressing, and these sad words Latona's daughter\nfrom her mouth was giving:""",
 """Meanwhile, in the dwellings on high, the daughter of Latona was speaking to swift Opis, one of the maidens who were her companions in her holy band, and these were the sorrowful words she uttered:""",
 """A new paragraph in Greenough: the scene moves from Turnus's ambush to heaven. 'Opim', Greek-style accusative of 'Opis', a nymph of Diana's company. 'unam ex virginibus sociis sacraque caterva', 'one of her companion maidens and holy band'. 'Latonia', 'Latona's daughter', Diana, the twin of Apollo. 'compellabat… dabat', imperfects: she was speaking when the battle began below. 'tristis… voces', '-is' accusative plural, 'sad words'; 'ore dabat', 'gave from her mouth', a full epic way of saying 'spoke'. Elisions 'Veloc(em) interea', 'un(am) ex'."""),
(537, 'alias.',
 """“Is marching to war, the cruel, Camilla,\nO maiden, and girds herself in vain with our arms,\ndear to me before others.""",
 """“Camilla is marching to a cruel war, maiden, and arms herself in vain with weapons of ours; she is dear to me above all others.""",
 """Diana's speech begins, and it runs on to 594. 'Graditur', 'steps, marches', put first, with the name held to the end of the line. 'nostris… armis', 'with our arms', the bow and quiver that are Diana's own weapons. 'nequiquam', 'in vain', tells the reader at once that Camilla will die. 'cingitur', passive in middle sense, 'girds herself'. 'cara mihi ante alias', 'dear to me before other women', 'alias' feminine. Elisions 'bell(um) ad', 'virg(o) et', 'mih(i) ante', 'ant(e) alias'."""),
(538, 'movit.',
 """For not new this of Diana\ncomes love, nor with a sudden sweetness has it moved my heart.""",
 """For this love of Diana's is no new thing, nor has it stirred my heart with a sudden sweetness.""",
 """The print has a closing double mark joined to 'Neque', as if Diana's speech ended at 'alias'; it does not, and the reading text leaves the mark out. Diana speaks of herself by name, 'Dianae', as gods often do (compare 'sola contenta Diana', 582), and the speech plainly goes on to 594. 'Neque enim', 'for… not'. 'novus… amor', framing; 'venit', 'has come'. 'subita… dulcedine', 'with sudden sweetness', a passing fancy. 'animum', understood as hers. Elisions 'Nequ(e) enim', 'subitaqu(e) animum'."""),
(543, 'Camillam.',
 """Driven, on account of hatred, from his kingdom and his proud strength,\nfrom Privernum, the ancient, when Metabus was departing, the city,\nthe infant, fleeing in the midst of the battles of war,\nhe took up as a companion for exile, and of her mother called her\nby the name, Casmilla, one part changed, Camilla.""",
 """When Metabus was driven from his throne because of the hatred his overbearing power had stirred, and was leaving the ancient city of Privernum, he took up his baby daughter in his flight, in the thick of the fighting, to share his exile, and named her Camilla, after her mother Casmilla, with one part of the name changed.""",
 """'Pulsus… regno', 'driven from his kingdom', ablative of separation. 'ob' governs both 'invidiam' and 'vires… superbas': 'because of hatred and his proud strength', in effect 'the hatred his tyranny roused'. 'Priverno… urbe', 'from the city of Privernum', a Volscian town in the hills south-east of Rome. 'cum excederet', 'when he was leaving'. 'sustulit', perfect of 'tollo', 'took up', as a father lifted a newborn to acknowledge it. 'matris… nomine Casmillae', 'by her mother's name, Casmilla', 'mutata parte', the 's' dropped. Servius connects 'camillus, camilla', a boy or girl who served a priest. Elisions 'Privern(o) antiqua', 'cu(m) excederet', 'medi(a) inter'."""),
(545, 'nemorum:',
 """He himself, in the fold of his robe before him carrying her, the long ridges was seeking\nof lonely woods:""",
 """He himself made for the long ridges of the lonely forests, carrying her before him in the fold of his robe:""",
 """'Ipse', Metabus, alone, with no one to carry the child for him. 'sinu', 'in the fold of his garment', the loose fold of cloth across the chest. 'prae se', 'in front of him'. 'iuga longa… solorum nemorum', 'the long ridges of lonely woods', the empty uplands where a fugitive might hide. 'petebat', the imperfect of an action in progress, interrupted in the lines that follow. No elisions."""),
(546, 'Volsci.',
 """weapons on every side, cruel, were pressing,\nand with soldiery poured around were flitting about the Volsci.""",
 """cruel weapons pressed on him from every side, and the Volscians darted all around him with their troops spread about him.""",
 """'tela… saeva premebant', 'cruel weapons were pressing (him)', the weapons for the men who threw them. 'circumfuso… milite', 'with soldiery poured round', an ablative of manner or attendant circumstance; 'miles' is collective. 'volitabant', frequentative of 'volo', 'fly', 'kept flitting about', the pursuers moving swiftly round him. The 'Volsci' are his own people, now his enemies. Elision 'tel(a) undique'."""),
(548, 'ripis:',
 """Look, in the middle of the flight, at the tops, Amasenus, overflowing,\nwas foaming of its banks:""",
 """See, there in the midst of his flight the Amasenus was foaming over, brimming to the tops of its banks:""",
 """'Ecce', 'look!', the storyteller's call to see the sudden obstacle. 'fugae medio', 'in the middle of the flight', 'medio' a neuter noun with the genitive. The Amasenus is a river of the Volscian country that runs past Privernum down to the Pomptine marshes. 'summis… ripis', 'at the tops of its banks', framing 'Amasenus abundans'. 'abundans', literally 'over-wave-ing', overflowing. 'spumabat', foaming with the flood. No elisions."""),
(549, 'ruperat.',
 """so great from the clouds a rain\nhad burst.""",
 """so heavy a rain had broken from the clouds.""",
 """'tantus… imber', 'so great a downpour', framing the clause. 'se… ruperat', 'had burst itself', a reflexive verb used where English uses an intransitive: the rain broke out of the clouds. 'nubibus', ablative of separation, 'from the clouds'. The pluperfect explains the flood: the storm had come before Metabus reached the river. No elisions."""),
(550, 'timet.',
 """He, to swim in preparing, by love of the infant\nis held back, and for his dear burden he fears.""",
 """He was ready to swim across, but love for the child held him back, and he feared for his precious burden.""",
 """'Ille', Metabus. 'innare parans', 'preparing to swim in', the river being the obstacle. 'infantis amore', 'by love of the infant', objective genitive. 'tardatur', 'is slowed', the historic present, as often in vivid narrative. 'caro… oneri timet', 'fears for his dear burden', 'timeo' with the dative of the person or thing one fears for. Elisions 'Ill(e) innare', 'caroqu(e) oneri'."""),
(551, 'sedit.',
 """All things with himself\nto him turning over, suddenly, scarcely, this decision settled.""",
 """As he turned every course over in his mind, all at once, and barely, this plan took hold.""",
 """'Omnia secum versanti', 'to him turning everything over with himself', dative of the person concerned, depending loosely on 'sedit': the decision settled 'for him'. 'secum', 'with himself', 'in his own mind'. 'subito vix', 'suddenly, (and) hardly': the plan came all at once, and he could barely bring himself to it. 'sententia sedit', 'the resolve was fixed', as a judge's sentence settles. No elisions."""),
(555, 'hastae;',
 """A weapon huge, which in his strong hand by chance he was carrying,\na warrior, solid with knots and oak seasoned by fire,\nto this his daughter, in bark and woodland cork enclosed,\nhe ties, and, handily, round the middle he binds of the spear;""",
 """He was a warrior, and he happened to be carrying in his strong hand a huge spear, solid with knots and fire-hardened oak; to this he tied his daughter, wrapped in bark and the cork of the woodland oak, and lashed her, well balanced, round the middle of the shaft;""",
 """The sentence begins with the spear, 'Telum immane', and picks it up again with 'huic' and 'hastae': the object is put first to fix attention, then resumed, a loose but vivid order. 'bellator', 'as a warrior', in apposition to the subject. 'robore cocto', 'oak baked', hardened in the fire. 'libro', from 'liber', 'inner bark'; 'subere', 'cork', from the cork-oak. 'habilem', 'handy', set so the spear balances. 'mediae… hastae', dative with 'circumligat'. Elisions 'Tel(um) immane', 'libr(o) et', 'atqu(e) habilem'."""),
(556, 'fatur:',
 """which in his huge right hand balancing, thus to the sky he speaks:""",
 """then, poising it in his mighty right hand, he spoke thus to the heavens:""",
 """'quam', connecting relative, 'and this (spear)'. 'librans', 'balancing, poising', the thrower's weighing of the shaft before the cast. 'dextra ingenti', 'in his huge right hand'. 'ad aethera', 'to the upper air', Greek accusative 'aethera'. 'fatur', the deponent 'for', 'speaks', in the historic present. Metabus's prayer, which follows, is a speech within Diana's speech. Elisions 'dextr(a) ingenti', 'it(a) ad'."""),
(559, 'fugit.',
 """‘Kindly one, to you this one, of the groves dweller, Latona's maiden daughter,\nI myself, her father, as a servant vow; your first through the airs\nweapons holding, a suppliant she flees the enemy.""",
 """‘Kind goddess, maiden daughter of Latona, who dwell among the groves, I her father vow this child to you as your handmaid; the first weapons she ever holds are yours, as she flies through the air, your suppliant, from the enemy.""",
 """The print sets Metabus's prayer in double marks inside Diana's speech; the reading text gives the nested speech single marks. 'Alma', 'nourishing, kindly', a cult title. 'nemorum cultrix', 'dweller in the groves', Diana's haunts. 'tibi hanc… famulam voveo', 'I vow this one to you as your servant', a formal vow. 'ipse pater', the father who may dispose of his child. 'tua prima… tela tenens', 'holding your weapons as her first': the spear is Diana's, the huntress's, and the first she grasps. Elision 'tib(i) hanc'."""),
(560, 'auris.”',
 """Receive, I beseech,\ngoddess, as your own, who now is entrusted to the doubtful breezes.’""",
 """Receive her, goddess, I implore you, as your own, for she is now entrusted to the uncertain winds.’""",
 """The print closes Metabus's prayer with a double mark; in the reading text it closes with a single one, since Diana is still speaking. 'Accipe', 'receive', the word of a god accepting an offering. 'testor', 'I call (you) to witness', here 'I implore'. 'diva tuam', 'goddess, (her as) your own', the two words set side by side. 'dubiis… auris', 'to the doubtful airs', framing 'committitur', 'is entrusted'. No elisions."""),
(562, 'immittit:',
 """He spoke, and with arm drawn back the whirled spear-shaft\nhe sends:""",
 """He spoke, drew back his arm, and sent the spear spinning on its way:""",
 """'Dixit', the closing formula of a speech, 'he spoke'. 'adducto… lacerto', ablative absolute, 'the upper arm drawn back', the throwing arm cocked. 'contortum hastile', 'the shaft whirled', given spin in the throw. 'immittit', 'sends at, launches', the historic present after the perfect. Elision 'contort(um) hastile'."""),
(563, 'Camilla.',
 """roared the waters, over the rapid river\nunhappy flees on the whistling javelin Camilla.""",
 """the waters roared, and over the racing river poor Camilla flew on the whistling javelin.""",
 """'sonuere' = 'sonuerunt', the perfect in '-ere' (you will meet it constantly). 'rapidum super amnem', 'over the swift river', 'super' placed between adjective and noun. 'infelix', 'unhappy, ill-starred', Diana's pity for a child whose life began in flight and will end in war. 'fugit', 'flees, flies', as the spear carries her. 'stridente', 'hissing, whistling', the sound of the shaft in flight. Elision 'sonuer(e) undae'."""),
(566, 'vellit.',
 """But Metabus, the great band now nearer pressing,\ngives himself to the river and the spear with the maiden, victorious,\nfrom the grassy, a gift to Trivia, turf plucks out.""",
 """But Metabus, now that the great band was pressing closer, plunged into the river, and on the other side, triumphant, pulled the spear with the girl on it, his gift to Trivia, out of the grassy turf.""",
 """'magna… caterva', ablative absolute with 'urgente', 'the great band pressing'. 'dat sese fluvio', 'gives himself to the river', plunges in. 'victor', 'victorious', over the flood and his pursuers. 'gramineo… de caespite', 'from the grassy turf', where the spear has stuck. 'donum Triviae', in apposition: the child is now Diana's. 'Trivia', 'goddess of the crossroads', a title of Diana as one with Hecate. Elisions 'i(am) urgente', 'fluvi(o) atque', 'atqu(e) hastam'."""),
(568, 'dedisset:',
 """Not him into houses did any, not within walls, cities\nreceive, nor would he himself in his wildness have given his hands:""",
 """No city took him in under its roofs or within its walls, nor, in his wild pride, would he himself have yielded:""",
 """'Non… ullae, non… urbes', 'no cities… none', the double negation hammering home his isolation. 'tectis… moenibus', datives or ablatives, 'into houses, within walls'. 'accepere' = 'acceperunt'. 'manus dare', 'to give one's hands', to surrender, as a captive holds out his hands to be bound: Metabus would not have bowed to any city. 'feritate', ablative of cause, 'in his wildness'. Elision 'nequ(e) ipse'."""),
(569, 'aevom.',
 """Among the shepherds' and the lonely mountains he passed his life.""",
 """He spent his days among the lonely mountains where only shepherds go.""",
 """'pastorum et solis… montibus', 'on the mountains of shepherds and lonely', the 'et' postponed: the mountains belong to herdsmen and are empty of towns. 'exegit', 'drove out, spent', of a lifetime. 'aevom', Greenough's old spelling of 'aevum', 'lifetime', keeping the early '-om' after 'v' as in 'divom' and 'volnus'. Elision 'pastor(um) et'."""),
(572, 'labris.',
 """Here his daughter in thickets and among the bristling lairs\nof a herd-mare at the teats and with milk wild\nhe nourished, milking the udders into her tender lips.""",
 """Here, among thorn-brakes and the bristling lairs of wild beasts, he reared his daughter on the teats of a mare from the herd and on wild creatures' milk, milking the udders into her tender lips.""",
 """'in dumis… horrentia lustra', 'in thickets… bristling dens', the haunts of wild animals. 'armentalis equae', 'of a mare of the herd', a brood mare running half-wild in the hills. 'lacte ferino', 'with milk of wild beasts': the story recalls the she-wolf that suckled Romulus and Remus. 'nutribat' = 'nutriebat', the old imperfect of a fourth-conjugation verb. 'immulgens', 'milking into', a rare compound. 'teneris… labris', framing 'immulgens ubera'. Elisions 'nat(am) in', 'interqu(e) horrentia'."""),
(575, 'arcum.',
 """And when, of her feet with the first soles, the infant footprints\nhad set, with a javelin her palms he armed, a sharp one,\nand arrows from the shoulder of the little one hung, and a bow.""",
 """And as soon as the child had planted her first footsteps with the soles of her feet, he armed her hands with a sharp javelin and hung arrows and a bow from the little girl's shoulder.""",
 """'Utque', 'and as soon as', 'ut' with the pluperfect 'institerat', 'had stood on'. 'pedum primis… vestigia plantis', 'footprints with the first soles of her feet', a fond, elaborate way of saying 'when she first walked'. 'iaculo… acuto', framing 'palmas armavit'. 'spicula', 'arrows', with 'arcum' added at the end. 'parvae', dative, 'from the little one's shoulder'. Elision 'spiculaqu(e) ex'."""),
(577, 'pendent.',
 """Instead of hair-gold, instead of a long robe's covering,\na tiger's spoils down her back from the crown of her head hang.""",
 """Instead of gold in her hair and the covering of a long robe, a tiger's skin hangs from her head down her back.""",
 """'Pro… pro', 'instead of… instead of', the anaphora setting what a girl of her birth should wear against what she does wear. 'crinali auro', 'hair-gold', gold pins or a net for the hair. 'palla', the long mantle of a grown woman. 'tigridis exuviae', 'a tigress's spoils', the stripped skin; the tiger is an exotic touch for Italy. The present 'pendent' brings the picture before our eyes. Elisions 'crinal(i) auro', 'dors(um) a'."""),
(580, 'olorem.',
 """Weapons with her hand already then tender childish she hurled,\nand the sling round her head she drove by its smooth thong,\nand a Strymonian crane or a white swan brought down.""",
 """Even then she was hurling a child's darts with her tender hand and whirling a sling round her head on its smooth thong, and bringing down a Strymonian crane or a white swan.""",
 """'iam tum', 'even then', while still a child. 'tela… puerilia', 'childish weapons', framing; 'manu… tenera', 'with tender hand'. 'fundam… egit', 'drove the sling round', whirled it. 'tereti… habena', 'with a smooth thong', framing 'circum caput'. 'Strymoniam… gruem', 'a Strymonian crane', from the Strymon in Thrace, where cranes gathered in poetry. 'olor', 'swan', a poetic word. Elision 'gru(em) aut'."""),
(582, 'nurum:',
 """Many her in vain through the Tyrrhenian towns mothers\nwished for as daughter-in-law:""",
 """Many a mother through the towns of Etruria longed in vain to have her as a son's bride:""",
 """'Multae… matres', framing the line. 'illam… optavere nurum', 'wished for her as daughter-in-law', 'nurum' predicative. 'optavere' = 'optaverunt'. 'Tyrrhena… oppida', the Etruscan towns, in whose country the Volscian exile lived near the border; mothers chose wives for their sons. 'frustra', 'in vain', held early. Elision 'Mult(ae) illam'."""),
(584, 'colit.',
 """alone content with Diana,\nan eternal love of weapons and of maidenhood\nundefiled she cherishes.""",
 """content with Diana alone, she cherishes, unsullied, an undying love for weapons and for maidenhood.""",
 """'sola contenta Diana', 'content with Diana alone', ablative with 'contenta': 'sola' is ablative here, agreeing with 'Diana'. Diana again names herself, as at 537. 'aeternum… amorem', framing 'telorum et virginitatis'. 'intemerata', 'unviolated', a solemn word. 'colit', 'cherishes', also used of tending a cult. The present tense: Camilla is still a virgin huntress now. Elision 'telor(um) et'."""),
(585, 'Teucros:',
 """I would wish she had not been seized\nby warfare such, having tried to provoke the Teucrians:""",
 """I could wish she had never been swept up into such a war, or tried to challenge the Trojans:""",
 """The print has an opening double mark before 'Vellem', as if a new speech began; Diana has been speaking since 535 and goes on, so the reading text leaves the mark out. 'Vellem… correpta fuisset', 'I would wish she had not been seized', an unfulfillable wish for the past: 'vellem' with the pluperfect subjunctive, 'ut' left out. 'correpta… militia tali', 'carried off by such soldiering'. 'conata', 'having tried'. 'Teucros', 'Teucrians', the Trojans. Elision 'Vell(em) haud'."""),
(586, 'mearum.',
 """dear to me and of my companions she would be now one.""",
 """she would still be dear to me, and one of my companions.""",
 """'foret', an old form equal to 'esset', the imperfect subjunctive of 'sum': the apodosis of the wish, 'she would (now) be'. 'cara mihi', picking up 535–537. 'comitum… una mearum', 'one of my companions', the genitive split around 'foret nunc'. The point is that she is dear now and will soon be lost. No elisions."""),
(589, 'pugna.',
 """But come, since by fates she is pressed bitter,\nglide down, nymph, from the sky, and the borders visit Latin,\nwhere the sad fight is joined under an unlucky omen.""",
 """But come, since bitter fate bears hard upon her, glide down from heaven, nymph, and go to the Latin lands, where a grim battle is being joined under evil omens.""",
 """The print has 'abere', a misprint for 'labere', corrected here. 'labere', imperative of the deponent 'labor', 'glide, slip down', the gods' swift descent. 'Verum age', 'but come', turning to action. 'quandoquidem', 'since in fact'. 'fatis… acerbis', 'by bitter fates', framing 'urgetur'. 'polo', 'from the sky', ablative of separation. 'finis… Latinos', '-is' accusative plural. 'tristis… pugna', framing; 'committitur', 'is joined'. Elisions 'Ver(um) age', 'finisqu(e) invise', 'ub(i) infausto'."""),
(590, 'sagittam:',
 """These take, and an avenging from the quiver draw out arrow:""",
 """Take these, and draw from the quiver an arrow of vengeance:""",
 """'Haec cape', 'take these', with a gesture: Diana hands Opis her bow and quiver. 'ultricem… sagittam', 'an avenging arrow', framing the line; 'ultrix' is the feminine of 'ultor', 'avenger'. 'pharetra', ablative of separation, 'from the quiver'. 'deprome', 'take out', a compound of 'promo'. Elision 'cap(e) et'."""),
(592, 'poenas.',
 """with this, whoever the sacred violates with a wound body,\nTrojan or Italian, to me equally let him give with blood the penalty.""",
 """with this let whoever wounds and violates her sacred body, Trojan or Italian, pay me alike the price in his blood.""",
 """'hac', 'with this (arrow)'. 'violarit' = 'violaverit', the future perfect contracted, 'shall have violated'. 'sacrum… corpus', framing 'violarit volnere': Camilla's body is sacred as Diana's votary. 'volnere', Greenough's spelling of 'vulnere'. 'Tros Italusque', 'Trojan or Italian', '-que' with the force of '-ve': whichever side. 'det… poenas', 'let him pay the penalty', jussive. 'sanguine', 'with his blood'. No elisions."""),
(594, 'reponam.”',
 """Afterwards I, in a hollow cloud, of the pitiable one the body and arms\nunspoiled will carry to the tomb and lay back in her homeland.”""",
 """Afterwards I myself, wrapped in a hollow cloud, will carry the poor girl's body and her arms, unplundered, to the tomb, and lay them to rest in her own country.”""",
 """Diana's speech ends. 'Post ego', 'afterwards I (myself)'. 'nube cava', 'in a hollow cloud', the gods' way of hiding and carrying. 'miserandae', gerundive, 'of the girl to be pitied'. 'inspoliata', 'unspoiled', not stripped by the victor, as armour usually was. 'tumulo', dative of goal, 'to the burial mound'. 'patriae… reponam', 'restore to her homeland'. In the Iliad Sleep and Death carry the dead Sarpedon home to Lycia, a scene Virgil may have in mind. No elisions."""),
(596, 'corpus.',
 """She spoke; but she, light, of heaven slipping down through the airs,\nsounded, wrapped about in a black whirlwind as to her body.""",
 """She spoke; and the nymph, gliding lightly down through the airs of heaven, went rushing and resounding, her body wrapped in a dark whirlwind.""",
 """'Dixit', the closing formula. 'at illa', 'but she', the other one, Opis. 'levis', 'light', nominative, of her swift and weightless descent. 'delapsa', from 'delabor', 'having glided down': she obeys 'labere' at 588. 'insonuit', 'made a sound', the rush of her passage. 'circumdata corpus', 'wrapped as to her body', the accusative with a passive participle in middle sense. 'nigro… turbine', framing. No elisions."""),
(599, 'turmas.',
 """But the force meanwhile to the walls Trojan approaches,\nand the Etruscan leaders and of horsemen the army whole,\narranged by number in squadrons.""",
 """Meanwhile the Trojan force was coming near the walls, with the Etruscan leaders and the whole host of horse, drawn up in squadrons of equal number.""",
 """A new paragraph in Greenough, back on earth. 'manus… Troiana', 'the Trojan band', framing. 'muris', dative with 'propinquat', 'approaches the walls'. 'propinquat' is singular with three subjects, agreeing with the nearest; 'compositi' then shifts to the plural by sense, the men. 'numero in turmas', 'into squadrons by number', in equal troops. Elisions 'equitumqu(e) exercitus', 'numer(o) in'."""),
(601, 'huc;',
 """Snorts over the plain whole\nprancing the charger and with pressed fights reins,\nthis way turned and this way;""",
 """Over the whole plain the charger snorts and prances, and fights against the tightened rein, swinging this way and that;""",
 """'Fremit', 'roars, snorts', put first. 'aequore toto', 'over the whole level', 'aequor', any flat expanse, here the plain. 'insultans', 'leaping on, prancing'. 'sonipes', 'sound-foot', a poetic word for a horse, used collectively for all the horses. 'pressis… habenis', ablative absolute, 'with reins held tight'; 'pugnat', 'fights', strains against them. 'huc… et huc', 'this way and this', to and fro. No elisions."""),
(602, 'ardent.',
 """then far and wide iron with spears\nbristles the field and the plains with arms raised blaze.""",
 """then far and wide the field bristles with iron spears, and the plains glitter with weapons held aloft.""",
 """'ferreus hastis… ager', 'the field iron with spears', framing: the spear-points make the field look like iron. 'horret', 'bristles', the word for hair standing on end, used of a field of spears, as of a cornfield. 'armis sublimibus', 'with arms held high'. 'ardent', 'blaze', of the flashing metal. Elision 'campiqu(e) armis'."""),
(607, 'equorum.',
 """Likewise Messapus opposite, and the swift Latins,\nand with his brother Coras, and of the maiden the wing, Camilla,\nfacing on the plain appear, and spears with drawn-back\nthey thrust out far right hands, and javelins they brandish,\nand the approach of men and the snorting grows hot of horses.""",
 """On the other side Messapus and the swift Latins, Coras with his brother, and the maiden Camilla's wing appear across the plain, facing them, and with right arms drawn back they thrust their spears far out and brandish their javelins, and the advance of men and the snorting of horses grow fiercer.""",
 """'Nec non', 'and also', two negatives making a positive. Messapus is the Etruscan-born horse-tamer of VII.691; Coras's brother is Catillus, the twins from Tibur (VII.670–672). 'virginis ala Camillae', 'the wing of the maiden Camilla', 'ala' the cavalry term. 'adversi', 'facing (them)'. 'reductis… dextris', 'with right hands drawn back', framing the spear-thrust. 'virum', old genitive plural, 'of men'. 'ardescit', singular with two subjects, 'catches fire'. Elisions 'camp(o) apparent', 'fremitusqu(e) ardescit'."""),
(609, 'substiterat:',
 """And now within the throw of a weapon having advanced each side\nhad halted:""",
 """And now each side had advanced to within a spear's throw and halted:""",
 """'intra iactum teli', 'within the cast of a spear', the distance at which battle begins. 'uterque', 'each of the two', the two armies, with a singular verb. 'progressus… substiterat', 'having advanced, had come to a stand', the pluperfect marking a pause before the sudden 'subito' that follows. Elision 'Iamqu(e) intra'."""),
(610, 'equos;',
 """suddenly they burst out with a shout, and frenzied\nthey urge on their horses;""",
 """suddenly they broke forward with a shout and urged on their maddened horses;""",
 """'erumpunt', 'they burst out', the historic present. 'clamore', 'with a shout', the battle cry. 'furentis… equos', '-is' accusative plural, 'raging horses'. The line ends in 'furentisque', and it has a syllable too many: the '-que' is elided into 'exhortantur' at the start of the next line. This 'hypermetric' line is rare in Virgil and usually suggests overflow, here of the charge. Elision 'subit(o) erumpunt'."""),
(611, 'umbra.',
 """they pour together from all sides weapons\nthick in the manner of snow, and the sky is covered with shadow.""",
 """from every side together they pour out showers of weapons, thick as snow, and the sky is darkened with their shadow.""",
 """'fundunt… tela', 'they pour weapons', as if liquid. 'simul undique', 'at once from everywhere'. 'crebra nivis ritu', 'thick in the manner of snow', 'ritu' with the genitive meaning 'like'; in the Iliad stones and missiles fall like snowflakes. 'obtexitur', 'is woven over', a covering of missiles that hides the light. Elision 'caelumqu(e) obtexitur'."""),
(615, 'rumpunt:',
 """At once with opposed, Tyrrhenus and keen Aconteus,\nstraining, charge spears, and first, with a crash\nhuge, give a sound, and the shattered of the gallopers\nchests with chests they break:""",
 """At once Tyrrhenus and fierce Aconteus, straining, charged at each other with levelled spears, and were the first to fall with a mighty crash, and the chests of their horses broke and shattered against each other:""",
 """'Tyrrhenus', an Etruscan on the Trojan side, against 'Aconteus', a Latin. 'adversis… hastis', 'with spears opposed'. 'conixi', from 'conitor', 'having strained'. 'ruina… ingenti', 'with a huge crash', framing 'dant sonitum'; the Latin Library reads 'ruinam dant sonitu ingenti', 'make a fall with a huge sound', but the print makes good sense and is kept. 'quadrupedantum', old genitive plural, 'of the galloping ones', the horses. 'pectora pectoribus', the repetition for the collision. Elisions 'Continu(o) adversis', 'conix(i) incurrunt', 'sonit(um) ingenti'."""),
(617, 'auras.',
 """thrown off, Aconteus,\nlike a thunderbolt or by an engine of a weight driven,\nhurls headlong far and his life scatters into the airs.""",
 """Aconteus was flung off like a thunderbolt or a stone shot from a war-engine, and was hurled far away headlong, scattering his life on the winds.""",
 """'excussus', 'shaken out', thrown from the saddle. 'fulminis in morem', 'in the manner of a thunderbolt', and 'in morem' governs the second genitive too: 'or (of) a weight driven by a catapult', 'tormento' the ablative of means. 'praecipitat', intransitive, 'falls headlong'. 'vitam dispergit in auras', 'scatters his life into the air': the life thought of as breath. Elisions 'mor(em) aut', 'long(e) et'."""),
(619, 'vertunt.',
 """Immediately thrown into confusion the lines, and turned the Latins\nthrow back their shields and their horses to the walls turn.""",
 """At once the ranks were thrown into disorder, and the Latins wheeled about, slung their shields on their backs and turned their horses toward the walls.""",
 """'turbatae (sunt) acies', with the verb left out. 'versi', 'turned', in flight. 'reiciunt parmas', 'throw back their small shields', slinging them over their backs to guard them as they flee. 'parma', the round cavalry shield. 'reiciunt' scans with its first syllable long, as if 'reiiciunt', a consonantal 'i' after a prefix. 'ad moenia', to the Latin city. Elision 'turbat(ae) acies'."""),
(620, 'Asilas.',
 """The Trojans drive them, first leads in the squadrons Asilas.""",
 """The Trojans pursued, and Asilas led the squadrons in at their head.""",
 """'Troes', Greek nominative plural, 'Trojans', here the whole Trojan and Etruscan force. 'agunt', 'drive (them)', in pursuit. 'princeps', 'foremost', in apposition: Asilas leads the charge. Asilas is the Etruscan seer and captain named in the catalogue of Aeneas's allies in Book X. 'inducit', 'leads in', against the enemy. No elisions."""),
(622, 'reflectunt:',
 """And now they were approaching the gates, and again the Latins\na shout raise and the pliant necks bend back:""",
 """And now they were nearing the gates, when the Latins raised a shout once more and wheeled their horses' supple necks around:""",
 """'propinquabant', imperfect, 'were getting near'; the subject is the pursuing Trojans. 'portis', dative. 'rursus', 'again', 'back': the Latins rally. 'clamorem tollunt', 'raise a shout'. 'mollia colla reflectunt', 'bend back the pliant necks', of their horses, turning them to face the enemy. No elisions."""),
(623, 'habenis.',
 """these flee, and far are carried back with given reins.""",
 """and now it was the others who fled, carried far back at full gallop.""",
 """'hi', 'these', now the Trojans and Etruscans, turning to flee. 'penitus', 'far, deep', 'right back'. 'datis… habenis', ablative absolute, 'with reins given', given free rein, at full speed. 'referuntur', 'are carried back', passive in middle sense. The tide turns; the simile follows. No elisions."""),
(628, 'relinquit:',
 """As when, with alternating running forward flood, the sea\nnow rushes to the land and over the rocks throws its wave,\nfoaming, and the farthest with its curve drenches sand,\nnow swift backward and, by the surge rolled back, sucking in\nthe stones it flees, and the shore, with the shallow sliding, leaves:""",
 """As when the sea comes running in with alternating flood, and now rushes at the land, flinging its foaming wave over the rocks and drenching the farthest sand in its curving sweep, and now flees swiftly backward, sucking down the stones that its surge has rolled, and leaves the shore as the shallows slide away:""",
 """The print has 'scopulusque', a misprint for 'scopulosque', corrected here: 'superiacit', 'throws over', needs an object, and 'spumeus' goes with 'pontus'. 'Qualis ubi', 'as when', opening the simile. 'alterno… gurgite', 'with alternating flood', the tide's ebb and flow. 'unda', ablative, 'with its wave'. 'sinu', 'with its curve'. 'arenam', Greenough's spelling of 'harenam'. 'revoluta… saxa', 'the stones rolled back'. 'vado labente', ablative absolute. Elisions 'ub(i) alterno', 'retr(o) atque', 'atqu(e) aestu'."""),
(630, 'tegentes.',
 """Twice the Tuscans the Rutulians drove to the walls, turned,\ntwice, thrown back, they look behind, their backs with arms covering.""",
 """Twice the Etruscans drove the Rutulians routed to the walls; twice they were thrown back in their turn, and looked behind them as they fled, covering their backs with their shields.""",
 """The simile applied: the two 'bis' clauses are the advance and the ebb. 'Tusci', the Etruscans; 'Rutulos', Turnus's people, standing for all the Latin side. 'egere' = 'egerunt'. 'versos', 'turned', in flight. In the second clause 'reiecti' is most naturally the Etruscans, thrown back in turn, though some take it of the Rutulians. 'respectant', frequentative, 'keep looking back'. 'terga tegentes', 'covering their backs' with shields. Elisions 'eger(e) ad', 'reiect(i) armis'."""),
(632, 'vir:',
 """The third but after, meeting, into battles whole\nthey entangled with each other lines, and picked man man:""",
 """But when they met for the third time and the whole lines locked together, and man singled out man:""",
 """'Tertia… in proelia', 'into the third battle', the plural used for a single clash. 'sed postquam', with 'sed' postponed. 'congressi', 'having come together'. 'implicuere' = 'implicuerunt', 'entangled'. 'totas… acies', 'the whole lines'. 'legit… virum vir', 'man chose man', each picking his opponent; here 'virum' is the accusative singular, not the old genitive plural of 607. Elisions 'congress(i) in', 'implicuer(e) inter', 's(e) acies'."""),
(635, 'surgit.',
 """then indeed both the groans of the dying, and in blood deep\nboth arms and bodies and, mingled with the slaughter of men,\nhalf-alive roll horses, the fight harsh rises.""",
 """then indeed the groans of the dying rose, and in deep blood weapons and bodies and half-dead horses rolled, mixed up with the slaughter of men, and a savage fight broke out.""",
 """'tum vero', 'then indeed', after 'postquam'. 'gemitus morientum', 'groans of the dying', 'morientum' the old genitive plural for 'morientium'; the verb for the groans is supplied from 'surgit' at the end. 'sanguine in alto', 'in deep blood'. 'armaque corporaque', the double '-que'. 'permixti caede virorum', 'mixed with the slaughter of men'. 'semianimes', four syllables, the 'i' consonantal. 'pugna aspera surgit', in asyndeton. Elisions 'ver(o) et', 'morient(um) et', 'sanguin(e) in', 'corporaqu(e) et', 'pugn(a) aspera'."""),
(637, 'reliquit.',
 """Orsilochus, of Remulus, since himself he shuddered to approach,\na spear hurled at the horse and the iron under the ear left.""",
 """Orsilochus, because he dreaded going against Remulus himself, hurled his spear at Remulus's horse and left the iron point lodged below its ear.""",
 """'Remuli' depends on 'equo' in the next line, 'at the horse of Remulus', and is set early to contrast with 'ipsum', 'the man himself'. Orsilochus is on the Trojan side, Remulus a Latin. 'quando', 'since'. 'horrebat adire', 'shrank from approaching', with an infinitive. 'intorsit', 'hurled with a twist'. 'ferrum… reliquit', 'left the iron (in the wound)'. Elisions 'quand(o) ipsum', 'ipsu(m) horrebat', 'hast(am) intorsit'."""),
(639, 'crura:',
 """At which blow the charger rages, rearing, and high flings,\nof the wound impatient, with breast raised, its legs:""",
 """At the blow the charger went wild and reared, and, unable to bear the wound, flung its legs high with its chest lifted up:""",
 """'Quo… ictu', connecting relative, 'at this blow'. 'sonipes', 'the charger', as at 600. 'arduus', 'steep, upright', rearing. 'alta… crura', 'high legs', framing the line, the forelegs thrown up. 'vulneris impatiens', 'not enduring the wound', the adjective with a genitive. 'vulneris' is printed with 'u' here, though Greenough elsewhere prints 'volnus'. 'arrecto pectore', ablative absolute. No elisions."""),
(640, 'humi.',
 """rolls he, thrown off, on the ground.""",
 """its rider was thrown and rolled on the ground.""",
 """'ille', Remulus, the rider, as against the horse. 'excussus', 'shaken off', as Aconteus was at 615. 'humi', locative, 'on the ground'. 'volvitur', passive in middle sense, 'rolls'. The brief sentence ends with a strong pause in the fourth foot. Elision 'ill(e) excussus'."""),
(643, 'terrent:',
 """Catillus Iollas\nand, huge in spirit, huge in body and arms,\nbrings down Herminius, on whose bare head tawny\nhair and bare his shoulders, nor wounds frighten him:""",
 """Catillus brought down Iollas, and Herminius, mighty in spirit, mighty in body and arms, whose head was bare with its tawny hair, and his shoulders bare, and wounds did not frighten him:""",
 """Catillus, brother of Coras, one of the twin founders of Tibur, now kills two men. 'Iollan', Greek accusative of 'Iollas'. 'ingentem animis, ingentem corpore', the repetition with change of reference. 'deicit', 'casts down', present. 'nudo cui vertice', 'to whom with bare head', 'cui', dative of possession, the verb supplied: 'he had tawny hair on his bare head, and bare shoulders'. 'caesaries', 'flowing hair'. Elisions 'ingentemqu(e) animis', 'corpor(e) et', 'nudiqu(e) umeri'."""),
(644, 'patet.',
 """so great, to arms he lies open.""",
 """so huge a target did he offer to the weapons.""",
 """'tantus… patet', 'so great is he (as he) lies open', the size of the unarmoured man making him an easy mark. 'in arma', 'to arms', 'exposed to weapons'. The short sentence explains the last, with 'tantus' echoing 'ingentem… ingentem'. No elisions."""),
(645, 'dolore.',
 """Broad, for him, the spear through the shoulders\ndriven quivers, and doubles the man up, piercing him, with pain.""",
 """The spear driven through his broad shoulders quivered there, and, having pierced him through, doubled him up with pain.""",
 """'huic', dative of disadvantage, 'for him', 'his'. 'Latos… per armos', 'through the broad shoulders', framing 'huic hasta'; 'armi' are shoulders, a word used mostly of animals, and it plays against 'arma' just before. 'acta', 'driven'. 'tremit', 'quivers', in the wound. 'duplicat… virum', 'doubles the man up'. 'transfixa', 'having transfixed', of the spear. 'dolore', ablative of cause. No elisions."""),
(646, 'cruor;',
 """Is poured, dark, everywhere the blood;""",
 """Dark blood flowed everywhere;""",
 """'Funditur', 'is poured out', placed first. 'ater… cruor', 'dark blood', framing 'ubique'; 'cruor' is blood shed from a wound, as against 'sanguis', blood in the body. The battle widens from single kills to the whole field. No elisions."""),
(647, 'mortem.',
 """they give deaths with the sword,\nstriving, and a beautiful they seek through wounds death.""",
 """vying with each other, they dealt death with the sword and sought a glorious death through wounds.""",
 """'dant funera', 'they give deaths', deal slaughter. 'ferro', 'with the sword', iron for the blade. 'certantes', 'competing', with each other in courage. 'pulchram… mortem', 'a beautiful death', framing 'petunt per vulnera': the 'fine death' in battle, the old heroic ideal. 'per vulnera', 'through wounds'. The part ends in the thick of the fight; Camilla's own exploits follow. No elisions."""),
]

# Speech-mark check exemptions (rule 5b / nested speech), by unit ln:
#  537: the print sets a closing mark joined to 'Neque' (537); Diana's speech runs on to 594, so l and i omit it.
#  557: Metabus's prayer opens with “ in the print; nested inside Diana's speech, so l and i use ‘.
#  559: Metabus's prayer closes with ” in the print (560); nested, so l and i use ’.
#  584: the print sets an opening mark before 'Vellem' (584) though Diana is still speaking; l and i omit it.
EXEMPT = {537, 557, 559, 584}
P = A.part('aeneid-087'); L = A.lines_of(P); paras = {l['n'] for l in L if l['p']}
cuts = A.cut(P, [(u[0], u[1]) for u in U])
sents = []; prev_end_line = None
for (t, ln), (_, _t, l, i, n) in zip(cuts, U):
    u = {'t': t, 'l': l, 'i': i, 'n': n}
    if prev_end_line != ln and ln in paras: u['p'] = True
    u['v'] = True; u['ln'] = ln; sents.append(u)
    prev_end_line = ln + t.count('\n')
    if t.count('\n') != l.count('\n'): print('LINE COUNT', ln, repr(t[:30]), t.count('\n'), l.count('\n'))
    if t.count('\n') > 4: print('TOO LONG', ln)
    if '\n' in i: print('NEWLINE IN i', ln)
    if t.rstrip('”]')[-1] not in A.TERMINAL + ',': print('ENDING', ln, repr(t[-12:]))
    nw = len(n.split())
    if nw > 139 or nw < 15: print('NOTE LENGTH', ln, nw)
    for mk in '“”[]':
        if t.count(mk) != l.count(mk) and ln not in EXEMPT: print('MARK l', ln, mk)
        if mk in '“”' and t.count(mk) != i.count(mk) and ln not in EXEMPT: print('MARK i', ln, mk)
    if '“' in n or '”' in n: print('DOUBLE MARK IN n', ln)
covered = sorted({ln + k for (t, ln) in cuts for k in range(t.count('\n') + 1)})
if covered != [l['n'] for l in L]: print('COVERAGE', covered)
joined = '\n'.join(l['t'] for l in L)
rebuilt = ''.join(t + ('\n' if (k + 1 < len(cuts) and cuts[k + 1][1] != ln + t.count('\n')) else ' ' if k + 1 < len(cuts) else '') for k, (t, ln) in enumerate(cuts))
if rebuilt != joined: print('JOIN MISMATCH')
if A.sha(L) != P.get('sha256', A.sha(L)): print('SHA MISMATCH')
A.jdump({'title': TITLE, 'titleEn': TITLE_EN, 'part': PART, 'about': ABOUT, 'sentences': sents}, os.path.join(HERE, 'units.json'))
print(len(sents), 'units;', len(covered), 'lines covered')
